#include "estimate.h"
#include <QRegularExpression>
#include <QStringList>

namespace {
int unitMinutes(QChar unit)
{
    switch (unit) {
    case 'w': return 5 * 8 * 60;
    case 'd': return 8 * 60;
    case 'h': return 60;
    case 'm': return 1;
    default: return 0;
    }
}
}

int parseEstimate(const QString &text)
{
    const QString trimmed = text.trimmed();
    if (trimmed.isEmpty())
        return -1;
    int total = 0;
    const QStringList parts = trimmed.split(QRegularExpression("\\s+"));
    for (const QString &part : parts) {
        if (part.size() < 2)
            return -1;
        const QChar unit = part.at(part.size() - 1);
        const int factor = unitMinutes(unit);
        if (factor == 0)
            return -1;
        bool ok = false;
        const int value = part.left(part.size() - 1).toInt(&ok);
        if (!ok || value < 0)
            return -1;
        total += value * factor;
    }
    return total;
}

QString formatEstimate(int minutes)
{
    if (minutes < 0)
        return {};
    QStringList out;
    int weeks = minutes / (5 * 8 * 60);
    minutes %= 5 * 8 * 60;
    int days = minutes / (8 * 60);
    minutes %= 8 * 60;
    const int hours = minutes / 60;
    minutes %= 60;
    if (weeks)
        out << QString::number(weeks) + "w";
    if (days)
        out << QString::number(days) + "d";
    if (hours)
        out << QString::number(hours) + "h";
    out << QString::number(minutes) + "m";
    return out.join(' ');
}

