        CHECK(spy.at(0).at(0).toInt(), 10);
        CHECK(spy.at(1).at(0).toInt(), 30);
        CHECK(spy.at(2).at(0).toInt(), 20);
        delete &mm;
        CHECK(s.openMinutes(), 0);
        CHECK(spy.count(), 4);
    }
    if (fails) { printf("%d FAILURES\n", fails); return 1; }
